const {readFileSync} = require('node:fs');
const kit = '/home/hatch/workspace/makefun/kits/csv-reader-speed-01-run-20261121/csv-reader-speed-01-run-20261121-kit';
const cases = JSON.parse(readFileSync(kit + '/practice/input/cases.json','utf8'));
let fields=0, quoted=0, doubled=0, multi=0, records=0, chars=0;
for (const c of cases) {
  const t = c.input.text; chars += t.length;
  // rough scan: count records by line, quoted fields by tracking
  let pos = t.charCodeAt(0)===0xFEFF?1:0;
  while (pos < t.length) {
    // skip empty lines
    while (pos < t.length && (t.charCodeAt(pos)===10 || (t.charCodeAt(pos)===13 && t.charCodeAt(pos+1)===10))) { pos += t.charCodeAt(pos)===10?1:2; }
    if (pos >= t.length) break;
    records++;
    while (true) {
      fields++;
      if (t.charCodeAt(pos)===34) {
        quoted++;
        let q = pos+1, hasD=false, hasNL=false;
        while (true) {
          const qi = t.indexOf('\"', q);
          if (qi===-1) { pos=t.length; break; }
          if (t.charCodeAt(qi+1)===34) { hasD=true; q=qi+2; continue; }
          const v = t.slice(pos+1, qi);
          if (v.indexOf('\n')!==-1||v.indexOf('\r')!==-1) hasNL=true;
          if (hasD) doubled++;
          if (hasNL) multi++;
          pos = qi+1;
          break;
        }
        if (pos>=t.length) break;
        const cc=t.charCodeAt(pos);
        if (cc===44){pos++;continue;}
        if (cc===10){pos++;break;}
        if (cc===13&&t.charCodeAt(pos+1)===10){pos+=2;break;}
        // junk: scan unquoted
        while (pos<t.length){const ch=t.charCodeAt(pos);if(ch===44){pos++;break;}if(ch===10){pos++;break;}if(ch===13&&t.charCodeAt(pos+1)===10){pos+=2;break;}pos++;}
        if (pos>=t.length) break;
        // after junk ended at comma continue, else record ends
        if (t.charCodeAt(pos-1)===44) continue; else break;
      } else {
        while (pos<t.length){const ch=t.charCodeAt(pos);if(ch===44){pos++;break;}if(ch===10){pos++;break;}if(ch===13&&t.charCodeAt(pos+1)===10){pos+=2;break;}pos++;}
        if (pos>=t.length) break;
        if (t.charCodeAt(pos-1)===44) continue; else break;
      }
    }
  }
}
console.log('chars:', chars, 'records:', records, 'fields:', fields, 'quoted:', quoted, (100*quoted/fields).toFixed(1)+'%', 'doubled:', doubled, 'multiline-quoted:', multi);
""}

