{"content":"// Supplementary fuzz: lone surrogates + structured generator-like inputs.
import { readFileSync } from 'node:fs';
import { run as mine } from '/home/hatch/workspace/makefun/csv-reader-20261121/repo/solve.js';
import { readCsv as ref } from '/home/hatch/workspace/makefun/kits/csv-reader-speed-01-run-20261121/csv-reader-speed-01-run-20261121-kit/baselines/csv-reader/vendor/csv-reader/index.js';

function rng(seed) {
  let s = seed >>> 0;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
}
const deepEqual = (a, b) => JSON.stringify(a) === JSON.stringify(b);
let n = 0, bad = 0;

// Lone surrogates and astral chars mixed with CSV metacharacters.
const alpha2 = ['\uD800', '\uDFFF', '\uD800\uDC00', '😀', 'é', ',', '"', '\n', '\r', 'a', '\uFEFF'];
for (let seed = 1; seed <= 2000; seed++) {
  const r = rng(seed + 100000);
  const k = Math.floor(r() * 12);
  let text = '';
  for (let i = 0; i < k; i++) text += alpha2[Math.floor(r() * alpha2.length)];
  const input = { text, header: r() < 0.5 };
  n++;
  if (!deepEqual(mine(input), ref(input))) {
    bad++;
    if (bad <= 3) console.log('SURROGATE MISMATCH', JSON.stringify(input));
  }
}

// Structured: generator-like records with multiline notes, CRLF, junk, unterminated tails.
const words = ['alpha', 'café', 'Москва', 'O\'Brien', 'a,b', 'x"y', 'naïve', ''];
for (let seed = 1; seed <= 500; seed++) {
  const r = rng(seed + 200000);
  const eol = r() < 0.5 ? '\r\n' : '\n';
  const width = 2 + Math.floor(r() * 6);
  const header = r() < 0.6;
  let text = r() < 0.3 ? '\uFEFF' : '';
  const mkField = () => {
    const w = words[Math.floor(r() * words.length)];
    const kind = r();
    if (kind < 0.15) return `"${w.replaceAll('"', '""')}"`; // needless quote
    if (kind < 0.25) return `"${w} ${words[Math.floor(r() * words.length)]}"`; // phrase
    if (kind < 0.32) return `"${w}${eol}${w} ${w}"`; // multiline note
    if (kind < 0.36) return `"${w}\r${w}"`; // lone CR inside quotes
    if (kind < 0.40) return `"${w}"${['kg', 'x', ' (est.)', 'x"y'][Math.floor(r() * 4)]}`; // junk
    if (kind < 0.44) return `${w}\r${w}`; // stray CR unquoted
    return w;
  };
  if (header) {
    text += Array.from({ length: width }, (_, i) => `col_${i + 1}`).join(',') + eol;
  }
  const nrec = 3 + Math.floor(r() * 20);
  for (let i = 0; i < nrec; i++) {
    if (r() < 0.05) text += eol; // blank line
    let flds = Array.from({ length: width }, mkField);
    if (r() < 0.08) flds = flds.slice(0, width - 1 - Math.floor(r() * 2)); // short
    else if (r() < 0.08) flds.push(mkField()); // long
    text += flds.join(',') + eol;
  }
  if (r() < 0.5) {
    // unterminated quote tail: opening quote, then bare records with no quotes
    text += '"tail start,more text' + eol;
    for (let i = 0; i < 3; i++) text += `plain${i},noline${i}` + eol;
  }
  if (r() < 0.3) text = text.slice(0, text.length - eol.length); // drop final EOL
  const input = { text, header };
  n++;
  if (!deepEqual(mine(input), ref(input))) {
    bad++;
    if (bad <= 3) console.log('STRUCTURED MISMATCH', JSON.stringify(input).slice(0, 400));
  }
}
console.log(`supplementary fuzz: ${n - bad}/${n} exact`);
","path":"/tmp/csv-fuzz2.mjs"}

